// 1. Recebe o JSON original vindo do nó MQTT
const dados = msg.payload;

// 2. Extrai e converte os valores estritamente para números (Float)
const campos = {
    sensor: "BME280",
    temperatura: parseFloat(dados.temperatura),
    pressao: parseFloat(dados.pressao),
    umidade: parseFloat(dados.umidade),
    timestamp: dados.timestamp * 1000
};

msg.payload = campos

return msg;

// =====================================================================
//  Nó "function" do Node-RED para o ensaio F3 (latência)
//  Ligação:  [mqtt in: casa/parametros/sensor1] -> [ESTE NÓ] -> [influxdb out]
//  No "influxdb out": measurement = latencia_f3 ; NÃO enviar hora
//  (o _time do ponto passa a ser o instante da gravação = T3)
//  Dica: ligue este ramo em PARALELO ao fluxo atual, a partir do mesmo
//  "mqtt in", para não mexer no que já funciona.
// =====================================================================

let p = msg.payload;
if (typeof p === "string") {
    try { p = JSON.parse(p); }
    catch (e) { node.warn("Payload não é JSON: " + msg.payload); return null; }
}

// Ignora mensagens do firmware antigo (sem os campos do F3)
if (p.ts_sensor_ms === undefined || p.seq === undefined) {
    node.warn("Mensagem sem ts_sensor_ms/seq: firmware do F3 não carregado?");
    return null;
}

const t2 = Date.now();                 // T2: chegada no Node-RED (ms, relógio do Windows)
const t0 = Number(p.ts_sensor_ms);     // T0: instante da publicação no ESP32 (ms, NTP)

msg.payload = [
    {   // fields
        temperatura: Number(p.temperatura),
        pressao: Number(p.pressao),
        umidade: Number(p.umidade),
        seq: Number(p.seq),
        ts_sensor_ms: t0,
        ts_nodered_ms: t2,
        lat_sensor_nodered_ms: t2 - t0
    },
    {   // tags
        sensor: "BME280",
        ensaio: "F3_A"
    }
];

// Mostra a latência no status do nó, para acompanhar ao vivo
node.status({ fill: "green", shape: "dot", text: `seq ${p.seq} | ${t2 - t0} ms` });

return msg;   // sem msg.payload[0].time  ->  _time = gravação (T3)
